'use client'

import { useId, useMemo, useState } from 'react'
import { children, compareBranches, forkPoints, leaves, pathTo, type Checkpoint, type StateChange } from './branches'
import { cx, formatWhen } from './util'

export type RunBranchesProps = {
  title: string
  /** Saved states of one run, each pointing at the one it came from. A run replayed from a step with something changed forks there. */
  checkpoints: Checkpoint[]
  /** Which two ends to compare first. Defaults to the first two. */
  defaultA?: string
  defaultB?: string
  className?: string
}

const show = (v: unknown) => (typeof v === 'string' ? `"${v}"` : JSON.stringify(v))
const VERB: Record<StateChange['kind'], string> = { added: 'Added', removed: 'Removed', changed: 'Changed' }

/** Depth-first, so each branch reads top to bottom under the checkpoint it split from. */
function order(cps: Checkpoint[]): { cp: Checkpoint; depth: number }[] {
  const out: { cp: Checkpoint; depth: number }[] = []
  const ids = new Set(cps.map((c) => c.id))
  const seen = new Set<string>()
  const walk = (c: Checkpoint, depth: number) => {
    if (seen.has(c.id)) return
    seen.add(c.id)
    out.push({ cp: c, depth })
    for (const k of children(cps, c.id)) walk(k, depth + 1)
  }
  for (const c of cps) if (!c.parentId || !ids.has(c.parentId)) walk(c, 0)
  for (const c of cps) walk(c, 0)
  return out
}

/**
 * One run seen as a tree of saved states. Where it was replayed from an earlier step with something changed, the tree
 * forks, and any two ends can be set side by side: where they split, what only each did, and exactly which saved
 * values differ at the end. Everything is read from the saved states, so nothing about the difference is guessed.
 */
export function RunBranches({ title, checkpoints, defaultA, defaultB, className }: RunBranchesProps) {
  const ends = useMemo(() => leaves(checkpoints), [checkpoints])
  const forks = useMemo(() => new Set(forkPoints(checkpoints).map((c) => c.id)), [checkpoints])
  const rows = useMemo(() => order(checkpoints), [checkpoints])
  const [a, setA] = useState(defaultA ?? ends[0]?.id ?? '')
  const [b, setB] = useState(defaultB ?? ends[1]?.id ?? ends[0]?.id ?? '')
  const base = useId()
  const cmp = useMemo(() => compareBranches(checkpoints, a, b), [checkpoints, a, b])
  const name = (id: string) => ends.find((e) => e.id === id)?.label ?? id
  if (checkpoints.length === 0) {
    return (
      <section role="group" className={cx('ol', className)} aria-label={title}>
        <div className="ol-head-row"><h3 className="ol-title">{title}</h3></div>
        <p className="ol-sub">No saved states for this run.</p>
      </section>
    )
  }
  return (
    <section role="group" className={cx('ol', className)} aria-label={title}>
      <div className="ol-head-row">
        <h3 className="ol-title">{title}</h3>
        <span className="ol-sub">{checkpoints.length} saved {checkpoints.length === 1 ? 'state' : 'states'}, {forks.size} {forks.size === 1 ? 'fork' : 'forks'}</span>
      </div>
      <ul className="ol-cptree" aria-label="Saved states">
        {rows.map(({ cp, depth }) => (
          <li key={cp.id} className="ol-cprow" style={{ paddingInlineStart: 8 + depth * 14 }} data-fork={forks.has(cp.id)} data-end={ends.some((e) => e.id === cp.id)} data-picked={cp.id === a ? 'a' : cp.id === b ? 'b' : undefined}>
            <span>{cp.label}</span>
            <span className="ol-sub">{formatWhen(cp.at)}{forks.has(cp.id) ? ' · the run forks here' : ''}{cp.id === a ? ' · A' : cp.id === b ? ' · B' : ''}</span>
          </li>
        ))}
      </ul>
      {ends.length > 1 && (
        <>
          <div className="ol-cppick">
            <label htmlFor={`${base}-a`}>Compare</label>
            <select id={`${base}-a`} className="ol-textarea" value={a} onChange={(e) => setA(e.target.value)}>{ends.map((e) => <option key={e.id} value={e.id}>{e.label}</option>)}</select>
            <label htmlFor={`${base}-b`}>with</label>
            <select id={`${base}-b`} className="ol-textarea" value={b} onChange={(e) => setB(e.target.value)}>{ends.map((e) => <option key={e.id} value={e.id}>{e.label}</option>)}</select>
          </div>
          <p role="status"  className="ol-my-3">{cmp.text}</p>
          {(cmp.onlyA.length > 0 || cmp.onlyB.length > 0) && (
            <div className="ol-cpsides">
              <div><p className="ol-sub">Only {name(a)}</p><ol>{cmp.onlyA.map((c) => <li key={c.id}>{c.label}</li>)}</ol></div>
              <div><p className="ol-sub">Only {name(b)}</p><ol>{cmp.onlyB.map((c) => <li key={c.id}>{c.label}</li>)}</ol></div>
            </div>
          )}
          {cmp.changes.length > 0 && (
            <table className="ol-table" aria-label="State differences">
              <thead><tr><th>Value</th><th>{name(a)}</th><th>{name(b)}</th></tr></thead>
              <tbody>
                {cmp.changes.map((c) => (
                  <tr key={c.path}><th scope="row">{c.path}</th><td>{c.kind === 'added' ? <span className="ol-sub">not set</span> : show(c.before)}</td><td>{c.kind === 'removed' ? <span className="ol-sub">removed</span> : show(c.after)}</td></tr>
                ))}
              </tbody>
            </table>
          )}
        </>
      )}
      {ends.length === 1 && <p className="ol-sub ol-mt-3">The run never forked, so there is one path: {pathTo(checkpoints, ends[0]!.id).length} states.</p>}
    </section>
  )
}

// Rules for comparing two paths through one run. The point of each: when an agent is replayed from a saved step with
// something changed, the page shows where the paths split and exactly which state differs, from the saved states
// themselves, and nothing a model said about the difference.

export type Checkpoint = {
  id: string
  /** The checkpoint this one came from. A checkpoint with two children is a fork. */
  parentId?: string
  label: string
  at: string
  /** The agent's state at this point. */
  values?: Record<string, unknown>
}
export type StateChange = { path: string; kind: 'added' | 'removed' | 'changed'; before?: unknown; after?: unknown }
export type BranchComparison = {
  /** The last checkpoint both paths share. Undefined when they share none. */
  divergedAt?: Checkpoint
  common: Checkpoint[]
  onlyA: Checkpoint[]
  onlyB: Checkpoint[]
  changes: StateChange[]
  text: string
}

/** From the first checkpoint to `id`. A cycle or a missing parent ends the walk instead of looping. */
export function pathTo(cps: Checkpoint[], id: string): Checkpoint[] {
  const byId = new Map(cps.map((c) => [c.id, c]))
  const out: Checkpoint[] = []
  const seen = new Set<string>()
  let cur = byId.get(id)
  while (cur && !seen.has(cur.id)) {
    seen.add(cur.id)
    out.unshift(cur)
    cur = cur.parentId ? byId.get(cur.parentId) : undefined
  }
  return out
}

export const children = (cps: Checkpoint[], id: string) => cps.filter((c) => c.parentId === id)
/** Ends of a path: checkpoints nothing continued from. */
export const leaves = (cps: Checkpoint[]) => cps.filter((c) => !cps.some((o) => o.parentId === c.id))
/** Checkpoints a run was replayed from with something changed: more than one child. */
export const forkPoints = (cps: Checkpoint[]) => cps.filter((c) => children(cps, c.id).length > 1)

const isObj = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v)
const same = (a: unknown, b: unknown) => JSON.stringify(a) === JSON.stringify(b)

/** Differences between two saved states. Objects are compared key by key and lists index by index. */
export function diffValues(a: unknown, b: unknown, path = ''): StateChange[] {
  if (same(a, b)) return []
  if (isObj(a) && isObj(b)) {
    return [...new Set([...Object.keys(a), ...Object.keys(b)])].sort().flatMap((k) => {
      const p = path ? `${path}.${k}` : k
      if (!(k in a)) return [{ path: p, kind: 'added' as const, after: b[k] }]
      if (!(k in b)) return [{ path: p, kind: 'removed' as const, before: a[k] }]
      return diffValues(a[k], b[k], p)
    })
  }
  if (Array.isArray(a) && Array.isArray(b)) {
    return Array.from({ length: Math.max(a.length, b.length) }, (_, i) => i).flatMap((i) => {
      const p = `${path}[${i}]`
      if (i >= a.length) return [{ path: p, kind: 'added' as const, after: b[i] }]
      if (i >= b.length) return [{ path: p, kind: 'removed' as const, before: a[i] }]
      return diffValues(a[i], b[i], p)
    })
  }
  return [{ path: path || '(whole state)', kind: 'changed', before: a, after: b }]
}

export function compareBranches(cps: Checkpoint[], aId: string, bId: string): BranchComparison {
  const a = pathTo(cps, aId)
  const b = pathTo(cps, bId)
  let k = 0
  while (k < a.length && k < b.length && a[k]!.id === b[k]!.id) k++
  const common = a.slice(0, k)
  const onlyA = a.slice(k)
  const onlyB = b.slice(k)
  const endA = a[a.length - 1]
  const endB = b[b.length - 1]
  const changes = endA && endB ? diffValues(endA.values ?? {}, endB.values ?? {}) : []
  const divergedAt = common[common.length - 1]
  let text: string
  if (!endA || !endB) text = 'One of the two checkpoints is not in the history.'
  else if (aId === bId) text = 'These are the same checkpoint.'
  else if (!divergedAt) text = 'These two paths never meet.'
  else if (onlyA.length === 0 || onlyB.length === 0) text = `One path continues from the other after "${divergedAt.label}".`
  else text = `The paths split after "${divergedAt.label}". One took ${onlyA.length} more ${onlyA.length === 1 ? 'step' : 'steps'} and the other ${onlyB.length}. They end ${changes.length === 0 ? 'in the same state' : `with ${changes.length} ${changes.length === 1 ? 'difference' : 'differences'} in state`}.`
  return { divergedAt, common, onlyA, onlyB, changes, text }
}
